function storageWarning(conflict=false){const warning=$('#storage-warning');if(!warning)return;warning.hidden=false;if(conflict)warning.textContent='Outra aba alterou os dados. Para evitar sobrescrever registros recentes, a gravação foi bloqueada. Copie a leitura ou exporte o cofre desta aba antes de recarregar.'}
