function geometry(c){const color=colors[c.suit],glyph=c.arcana==='Maior'?majorGlyph[c.rank]:symbols[c.suit],n=c.rank;return '<svg viewBox="0 0 200 280" aria-hidden="true"><rect width="200" height="280" fill="#141424"/><circle cx="100" cy="125" r="77" fill="#24203d" stroke="'+color+'" opacity=".9"/><circle cx="100" cy="125" r="66" fill="none" stroke="'+color+'" stroke-dasharray="2 5"/><path d="M0 235 L60 174 100 212 140 174 200 235 V280 H0Z" fill="#302940"/><path d="M0 260 L100 198 200 260" fill="none" stroke="'+color+'" opacity=".6"/><path d="M100 48 156 125 100 202 44 125Z" fill="none" stroke="'+color+'" opacity=".8"/><text x="100" y="148" text-anchor="middle" font-size="58" font-family="Georgia, serif" fill="'+color+'">'+glyph+'</text><text x="100" y="32" text-anchor="middle" font-size="12" fill="'+color+'">'+String(n).padStart(2,'0')+'</text>'+Array.from({length:12},(_,i)=>'<circle cx="'+(100+88*Math.cos(i*Math.PI/6))+'" cy="'+(125+88*Math.sin(i*Math.PI/6))+'" r="1.5" fill="'+color+'"/>').join('')+'</svg>'}
const knownArt = new Map(),observedImages=new WeakSet();
let atlasLimit=24,deckScroll=0;let motion=read('arcana-motion',true)!==false;let revealing=false;let revealGeneration=0;let releaseReveal=()=>{};let ambience=false,ambientTicket=0,flight=null;const calm=()=>!motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
function artImage(id,lazy=true,size='(max-width: 620px) 180px, 300px',alt=''){const formats=knownArt.has(id)?[knownArt.get(id)]:['png','webp','jpg','jpeg'];const original='./assets/cards/'+id+'.'+formats[0];const src=optimizedArt?'./assets/optimized/'+id+'-420.webp':original;const variants=optimizedArt?' data-optimized="true" srcset="./assets/optimized/'+id+'-420.webp 420w, ./assets/optimized/'+id+'-1050.webp 1050w" sizes="'+esc(size)+'"':'';return '<img data-art="'+id+'" data-formats="'+formats.join(',')+'" src="'+src+'"'+variants+' alt="'+esc(alt)+'" '+(lazy?'loading="lazy" ':'fetchpriority="high" ')+'decoding="async" draggable="false" class="pending-art protected-art">'}
function card(c,rev=false,reveal=false){const face='<div class="tarot '+(rev?'upside ':'')+'"><div class="art">'+geometry(c)+artImage(c.id,!reveal)+'</div><div class="plate">'+esc(c.name)+'</div></div>';return reveal?'<div class="flip-stage"><div class="flip-object"><div class="flip-back" aria-hidden="true">'+back()+'</div><div class="flip-front">'+face+'</div></div></div>':face}
function back(){return '<div class="tarot back"><svg viewBox="0 0 200 280" aria-hidden="true"><g fill="none" stroke="#c6a46c"><rect x="10" y="10" width="180" height="260" rx="6"/><rect x="17" y="17" width="166" height="246" rx="4" opacity=".4"/><circle cx="100" cy="140" r="65"/><circle cx="100" cy="140" r="49" stroke-dasharray="3 5"/><path d="M100 55 156 140 100 225 44 140Z M35 140H165 M100 75V205 M100 23l10 10-10 10-10-10Z M100 237l10 10-10 10-10-10Z"/><circle cx="100" cy="140" r="24"/><path d="M100 116a24 24 0 0 0 0 48a15 24 0 0 1 0-48Z" fill="#c6a46c"/></g></svg>'+artImage('back')+'</div>'}
function watchImages(root=view){root.querySelectorAll('img[data-art]').forEach(img=>{if(observedImages.has(img))return;observedImages.add(img);const id=img.dataset.art,formats=img.dataset.formats.split(',');let index=0;const loaded=()=>{if(img.naturalWidth){if(!img.dataset.optimized)knownArt.set(id,formats[index]);img.classList.remove('pending-art');img.closest('.art,.back')?.classList.add('has-art')}};const failed=()=>{if(img.dataset.optimized){delete img.dataset.optimized;img.removeAttribute('srcset');img.removeAttribute('sizes');img.src='./assets/cards/'+id+'.'+formats[index];return}if(++index>=formats.length){img.remove();return}img.src='./assets/cards/'+id+'.'+formats[index]};img.addEventListener('load',loaded);img.addEventListener('error',failed);if(img.complete){if(img.naturalWidth)loaded();else failed()}})}
function toast(text){$('#toast').textContent=text;clearTimeout(timer);timer=setTimeout(()=>$('#toast').textContent='',2800)}
let lastChime=0;function chime(){if(!sound||document.hidden||performance.now()-lastChime<120)return;lastChime=performance.now();try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime;[392,587.33,783.99].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t+i*.08);g.gain.exponentialRampToValueAtTime(.045,t+i*.08+.06);g.gain.exponentialRampToValueAtTime(.0001,t+i*.08+.65);o.connect(g);g.connect(audio.destination);o.start(t+i*.08);o.stop(t+i*.08+.7);o.onended=()=>{o.disconnect();g.disconnect()}})}catch{}}
const controlIcons={ambient:'<path d="M9 18V5l11-2v13M9 7l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2.5"/><ellipse cx="17" cy="16" rx="3" ry="2.5"/>',sound:'<path d="M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/>',motion:'<circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-40 12 12)"/><path d="M7 4l1 2M17 18l1 2"/>'};
function renderControl(id,enabled,label){const b=$('#'+id);b.setAttribute('aria-pressed',String(enabled));b.setAttribute('aria-label',label);b.title=label+(enabled?' · ativo':' · desativado');b.innerHTML='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+controlIcons[id]+(enabled?'':'<path class="control-slash" d="M3 3l18 18"/>')+'</svg>'}
function syncSettings(){document.body.dataset.immersion='cinematic';document.body.classList.toggle('motion-off',!motion);renderControl('motion',motion,'Animações');renderControl('sound',sound,'Sons de interação');renderControl('ambient',ambience,'Áudio ambiente')}syncSettings();bindAtmosphere();$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'})});$('#sound').onclick=()=>{sound=!sound;write('arcana-sound',sound);syncSettings();chime()};$('#motion').onclick=()=>{motion=!motion;write('arcana-motion',motion);syncSettings();if(calm())cancelReveal()};$('#ambient').onclick=async()=>{const ticket=++ambientTicket;ambience=!ambience;syncSettings();const ok=await ambient(ambience,document.body.dataset.scene);if(ticket===ambientTicket&&ambience&&!ok&&!document.hidden){ambience=false;syncSettings();toast('O áudio ambiente não pôde ser iniciado.')}};document.addEventListener('visibilitychange',()=>{if(document.hidden){stopNarration();pauseAmbient()}else if(ambience)ambient(true,document.body.dataset.scene)});
function dailyCard(){const day=localDay();if(!daily||daily.day!==day||!deck.some(c=>c.id===daily.item?.id)||daily.item?.reversed!==false){daily={day,item:draw(1)[0]};write('arcana-daily-v1',daily)}return resolve(daily.item)}
function home(){view.innerHTML='<section class="hero"><div class="hero-copy"><p class="eyebrow">O Portal · O baralho autoral</p><h1>Entre o visível<br>e o invisível.</h1><p class="lead">Escolha as cartas, leia seus símbolos e descubra novas maneiras de olhar para o que está vivendo.</p><div class="actions"><a class="primary" href="#ritual">'+(session?'Retomar minha tiragem':'Começar uma tiragem')+' <span aria-hidden="true">→</span></a><a class="text-link" href="#atlas">Conhecer o baralho</a></div><p class="hero-note">22 Arcanos Maiores e 56 Arcanos Menores.<br>Um espaço de reflexão, sem respostas predeterminadas.</p></div><figure class="hero-plate"><div class="hero-cards">'+runeHalo(deck[18].id,true)+'<div class="hero-side hero-left" aria-hidden="true">'+card(deck[17])+'</div><div class="plate-mount">'+card(deck[18])+'</div><div class="hero-side hero-right" aria-hidden="true">'+card(deck[19])+'</div></div><figcaption><span>A Estrela · A Lua · O Sol</span><span>Arcanos Maiores</span></figcaption></figure></section><section class="feature-strip" aria-labelledby="how-it-works"><h2 id="how-it-works" class="sr-only">Como funciona</h2><article><span class="chapter">I.</span><h3>Faça uma pergunta</h3><p class="muted">Escolha um tema e a tiragem que melhor se ajusta a ele.</p></article><article><span class="chapter">II.</span><h3>Escolha suas cartas</h3><p class="muted">Revele os arcanos um de cada vez ou registre seu próprio baralho.</p></article><article><span class="chapter">III.</span><h3>Leia os símbolos</h3><p class="muted">Explore como as cartas se relacionam e registre suas reflexões.</p><a class="text-link" href="#journey">Jornada do Louco →</a></article></section><section class="daily-feature"><div class="daily-symbol" aria-hidden="true">'+back()+'</div><div><p class="eyebrow">Um ritual cotidiano</p><h2>A carta de hoje</h2><p class="muted">Uma imagem para acompanhar suas reflexões ao longo do dia.</p><a class="text-link" href="#daily">Revelar a carta do dia <span aria-hidden="true">→</span></a></div></section>';watchImages()}
function setup(){view.innerHTML='<section class="section-head"><p class="eyebrow">O Santuário · 01 · Intenção</p><h1>Prepare sua tiragem</h1><p class="lead">Uma pergunta aberta permite examinar escolhas, sem pedir certeza sobre o futuro.</p><a class="text-link" href="#architect">Criar ou editar um ritual personalizado →</a></section><form id="setup" class="panel"><div class="fields"><label>Área da vida<select name="topic">'+Object.entries(topics).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label>Tipo de tiragem<select name="spread">'+Object.entries(spreads).map(([k,v])=>'<option value="'+k+'" '+(!selectedTemplate&&k==='three'?'selected':'')+'>'+v.name+' · '+v.positions.length+' carta(s)</option>').join('')+customTemplates.map(t=>'<option value="custom:'+t.id+'" '+(selectedTemplate===t.id?'selected':'')+'>'+esc(t.definition.name)+' · '+t.definition.positions.length+' carta(s)</option>').join('')+'</select></label><div class="spread-preview wide" id="spread-preview" aria-live="polite"></div><label class="wide">Sua pergunta (opcional)<textarea name="question" rows="3" maxlength="1000" placeholder="O que posso compreender sobre este momento?"></textarea></label><label class="wide">Modo de seleção<select name="mode"><option value="choose">Escolher cartas do baralho embaralhado</option><option value="random">Sortear automaticamente</option><option value="manual">Informar cartas do meu baralho físico</option></select></label></div><label class="check"><input name="reverse" type="checkbox"> Incluir cartas invertidas</label><div class="actions"><button class="primary">Preparar o baralho</button></div></form>';const chosen=()=>{const value=$('#setup [name=spread]').value;return value.startsWith('custom:')?{key:'custom',definition:customTemplates.find(t=>t.id===value.slice(7))?.definition}:{key:value,definition:null}};const preview=()=>{const {key,definition}=chosen(),sp=spreadFor(key,definition);if(!sp)return;$('#spread-preview').innerHTML='<span class="eyebrow">Mapa da tiragem</span><div class="mini-spread">'+sp.positions.map((p,i)=>'<span><i>'+(i+1)+'</i>'+esc(p)+'</span>').join('')+'</div>'};$('#setup [name=spread]').onchange=preview;preview();$('#setup').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),{key:spread,definition}=chosen(),sp=spreadFor(spread,definition);if(!sp)return;selectedTemplate='';session={spread,...(spread==='custom'?{customSpread:snapshot(definition)}:{}),topic:f.get('topic'),question:f.get('question').trim(),reverse:f.has('reverse'),mode:f.get('mode'),items:f.get('mode')==='random'?draw(sp.positions.length,f.has('reverse')):[],revealed:0,chat:[],note:'',saved:false};if(session.mode==='choose')session.pool=draw(78,session.reverse);deckScroll=0;persist();chime();ritual(true)}}
function runeReading(s,active){const items=s.items.slice(0,s.revealed);if(!items.length)return '<section class="rune-altar dormant"><p class="eyebrow">Círculo dos arcanos</p><p>Os sigilos despertarão com a primeira carta.</p></section>';const complete=s.revealed===spreadFor(s.spread,s.customSpread).positions.length;return '<section class="rune-altar '+(complete&&active>=0?'altar-complete':'')+'" aria-label="Círculo dos arcanos"><div class="altar-visual">'+constellation(items,active)+'</div><div class="altar-copy"><p class="eyebrow">Círculo dos arcanos</p><h3>'+(complete?'A mandala da tiragem':'A constelação se forma')+'</h3><p class="muted">'+(complete?'Os sigilos se unem em uma composição que registra as cartas e suas relações.':'Cada carta revelada acrescenta seu sigilo ao círculo.')+'</p><div class="rune-legend">'+items.map((item,i)=>{const c=resolve(item);return '<span style="--rune:'+sigilInfo(item.id).color+'"><i aria-hidden="true"></i>'+esc(c.name)+(item.reversed?' · invertida':'')+'</span>'}).join('')+'</div><small>Sigilos autorais do ARCANA, sem atribuição histórica ou poder preditivo.</small></div></section>'}
function ritual(shuffle=false,flipping=-1){if(!session){setup();return}const s=session,sp=spreadFor(s.spread,s.customSpread),cells=layoutCells(sp.positions.length,sp.layout),done=s.revealed===sp.positions.length;view.innerHTML='<section class="section-head"><div class="steps"><span>01 Intenção</span><span>›</span><span '+(!done?'class="step-current" aria-current="step"':'')+'>02 Revelação</span><span>›</span><span '+(done?'class="step-current" aria-current="step"':'')+'>03 Reflexão</span></div><p class="eyebrow">'+esc(topics[s.topic])+'</p><h1 class="ritual-title">'+esc(sp.name)+'</h1><p class="lead">'+(s.question?esc(s.question):'Revele as cartas na ordem indicada.')+'</p></section><div class="panel ritual-table"><div class="ritual-progress"><p role="status">'+s.revealed+' de '+sp.positions.length+' cartas reveladas</p><progress max="'+sp.positions.length+'" value="'+s.revealed+'" aria-label="Progresso da tiragem"></progress></div><div class="ritual-next" aria-live="polite">'+(done?'<span>O círculo está completo.</span><button id="to-reading" class="primary">Ler interpretação ↓</button>':'<span>Próxima posição: <strong>'+esc(sp.positions[s.revealed])+'</strong></span>')+'</div><div class="spread spread-'+s.spread+' '+(s.spread==='custom'?'custom-'+sp.layout+(cells.length?' custom-ring':''):'')+' '+(shuffle?'shuffle':'')+'" style="--custom-count:'+sp.positions.length+'">'+sp.positions.map((p,i)=>'<div class="slot '+(i===flipping?'slot-awake ':'')+(i===s.revealed?'slot-next':'')+'"'+(cells[i]?' style="--cell-x:'+cells[i][0]+';--cell-y:'+cells[i][1]+'"':'')+'><span class="position">'+(i+1)+' · '+esc(p)+'</span><button data-slot="'+i+'" aria-label="'+esc(i<s.revealed?'Ver '+resolve(s.items[i]).name:'Revelar carta '+(i+1))+'" '+(i>s.revealed?'disabled':'')+'>'+(i<s.revealed?runeHalo(s.items[i].id,i===flipping):'')+(i<s.revealed?card(resolve(s.items[i]),s.items[i].reversed,i===flipping):back())+'</button>'+(i<s.revealed?'<small>'+(s.items[i].reversed?'Invertida':'Normal')+'</small>':'')+'</div>').join('')+'</div>'+(s.mode==='choose'&&!done?selectionTray(s):s.mode==='manual'&&!done?'<form id="manual" class="fields"><label>Escolha a carta para '+esc(sp.positions[s.revealed])+'<select name="card" required><option value="">Selecione…</option>'+deck.filter(c=>!s.items.some(i=>i.id===c.id)).map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Orientação<select name="orientation"><option value="normal">Normal</option><option value="reverse">Invertida</option></select></label><button class="primary">Confirmar carta</button></form>':!done?'<button id="reveal-next" class="primary">Revelar próxima carta</button>':'')+runeReading(s,flipping)+'<div class="actions"><button id="reset" class="secondary">Nova tiragem</button></div></div>'+(done?reading(): '');watchImages();if($('#to-reading'))$('#to-reading').onclick=()=>{const el=$('#reading');el.focus({preventScroll:true});el.scrollIntoView({behavior:calm()?'instant':'smooth',block:'start'})};const tray=$('.deck-tray');if(tray){tray.scrollLeft=deckScroll;tray.onscroll=()=>{deckScroll=tray.scrollLeft};view.querySelectorAll('[data-deck-dir]').forEach(b=>b.onclick=()=>tray.scrollBy({left:Number(b.dataset.deckDir)*tray.clientWidth*.7,behavior:calm()?'instant':'smooth'}));$('#quick-pick').onclick=()=>pick(Math.floor(Math.random()*s.pool.length),$('#quick-pick'))}view.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.slot);if(i<s.revealed)showCard(resolve(s.items[i]),s.items[i].reversed);else if(s.mode==='random')reveal();else if(s.mode==='choose')view.querySelector('[data-pick]')?.focus();else $('#manual select').focus()});view.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>pick(Number(b.dataset.pick),b));if($('#reveal-next'))$('#reveal-next').onclick=reveal;if($('#manual'))$('#manual').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(revealing||!f.get('card')||s.items.some(i=>i.id===f.get('card')))return;s.items.push({id:f.get('card'),reversed:f.get('orientation')==='reverse'});reveal()};$('#reset').onclick=()=>{if(!s.saved&&!confirm('Iniciar outra tiragem sem salvar esta?'))return;stopNarration();cancelReveal();session=null;deckScroll=0;persist();setup()};if(done)bindReading()}
function selectionTray(s){return '<section class="selection-tray"><p class="eyebrow">Escolha intuitiva</p><h3>Qual carta chama sua atenção?</h3><p class="muted">'+s.pool.length+' cartas disponíveis. Percorra o baralho e escolha uma; todas têm a mesma probabilidade antes de serem reveladas.</p><div class="deck-controls"><button type="button" class="secondary" data-deck-dir="-1" aria-label="Cartas anteriores">‹</button><button id="quick-pick" class="secondary" type="button">Escolher ao acaso</button><button type="button" class="secondary" data-deck-dir="1" aria-label="Próximas cartas">›</button></div><div class="deck-tray" aria-label="Baralho embaralhado">'+s.pool.map((_,i)=>'<button class="pick-card" data-pick="'+i+'" aria-label="Escolher carta fechada '+(i+1)+'">'+back()+'</button>').join('')+'</div></section>'}
function pick(i,source){if(!session||session.mode!=='choose'||session.revealed>=spreadFor(session.spread,session.customSpread).positions.length)return;if(revealing)return;const next=chooseFromPool(session.pool,i);session.pool=next.remaining;session.items.push(next.item);reveal(source?.getBoundingClientRect())}
function cancelReveal(){flight?.cancel();flight=null;revealGeneration++;releaseReveal();releaseReveal=()=>{};revealing=false}
function reveal(origin){if(revealing||!session||session.revealed>=session.items.length)return;const index=session.revealed;session.revealed++;persist();chime();ritual(false,index);const slot=view.querySelector('[data-slot="'+index+'"]');slot?.focus({preventScroll:true});if(slot){const r=slot.getBoundingClientRect();if(r.top<0||r.bottom>innerHeight)slot.scrollIntoView({block:'center',behavior:calm()?'instant':'smooth'})}if(!calm()){const ticket=++revealGeneration;revealing=true;const controls=[...view.querySelectorAll('[data-pick],#quick-pick,#reveal-next,#manual button')];controls.forEach(b=>b.disabled=true);releaseReveal=()=>{controls.forEach(b=>{if(b.isConnected)b.disabled=false});revealing=false};const stage=slot?.querySelector('.flip-stage');flight=animateArrival(stage,origin);const animations=[...(slot?.querySelector('.flip-object')?.getAnimations()||[]),...(flight?[flight]:[])];Promise.allSettled(animations.map(a=>a.finished)).then(()=>{if(ticket===revealGeneration){releaseReveal();releaseReveal=()=>{};flight=null}})}}
function profile(r){return '<div class="profile"><div><small>Arcanos maiores</small><strong>'+r.profile.major+'</strong></div><div><small>Invertidas</small><strong>'+r.profile.reversed+'</strong></div><div><small>Relações</small><strong>'+r.combos.length+'</strong></div></div><div class="element-profile">'+Object.entries(r.profile.counts).map(([k,v])=>'<div><span>'+esc(k)+'</span><span class="element-track"><i style="width:'+Math.round(v/r.cards.length*100)+'%"></i></span><strong>'+v+'</strong></div>').join('')+'</div>'}
function combinationList(r){const render=c=>'<article><strong>'+esc(c.title)+'</strong><p>'+esc(c.text)+'</p></article>';const others=r.combos.filter(c=>!c.adjacent);return r.combos.filter(c=>c.adjacent).map(render).join('')+(others.length?'<details class="extra-combos"><summary>Explorar mais '+others.length+' combinações</summary>'+others.map(render).join('')+'</details>':'')}
function reading(){const s=session,r=interpret(s.items,s.spread,s.topic,s.customSpread),o=oracleReading(s);return '<section class="panel reading reading-arrival" id="reading" tabindex="-1"><p class="eyebrow">03 · Reflexão</p><h2>O diálogo das cartas</h2><div class="reading-jumps"><button class="secondary" data-jump="chat-section">Conversar</button><button class="secondary" data-jump="journal-note">Anotar</button></div><section class="oracle-synthesis"><p class="eyebrow">Síntese contextual · '+esc(o.title)+'</p><p class="lead">'+esc(o.narrative)+'</p>'+(s.question?'<p class="muted">'+(o.recognized?'Tema reconhecido por palavras-chave e área selecionada.':'Nenhum tema específico reconhecido; a leitura usa as posições e os símbolos.')+'</p>':'')+'<p><strong>Prática:</strong> '+esc(o.practice)+'</p><p class="study-question">'+esc(o.question)+'</p><div class="actions"><button id="narrate" class="secondary">Ouvir leitura neural</button><button id="stop-narration" class="secondary" disabled>Parar áudio</button></div><p id="narration-status" role="status" class="muted"></p></section><p class="muted">'+esc(r.summary)+'</p>'+profile(r)+r.cards.map(c=>'<article><small>'+esc(c.position)+' · '+(c.isReversed?'Invertida':'Normal')+'</small><h3>'+esc(c.name)+'</h3><p>'+esc(c.reading)+'</p><p>'+esc(c.study.depth)+'</p><p class="muted">'+esc(c.study.question)+'</p><p class="muted">Prática: '+esc(c.action)+'.</p></article>').join('')+'<h3 class="result-title">Combinações</h3>'+(r.combos.length?combinationList(r):'<p>Uma única carta concentra a reflexão no seu significado.</p>')+'<h3 class="result-title">Pergunta para levar consigo</h3><p>'+esc(r.focus)+'</p></section><section class="panel reading" id="chat-section" tabindex="-1"><p class="eyebrow">Oráculo ARCANA · Modo local</p><h2>Converse sobre sua leitura</h2><p class="muted">Explore sua pergunta, os arcanos, as posições e o contexto recente da conversa. O oráculo usa regras locais, não IA generativa; nenhum texto da leitura é enviado a um servidor.</p><div id="chat" class="chat" aria-live="polite"></div><div class="actions"><button class="secondary" data-ask="Explique as combinações">Combinações</button><button class="secondary" data-ask="Qual é o conselho prático?">Conselho</button><button class="secondary" data-ask="Explique as sombras">Sombras</button><button class="secondary" data-ask="Aprofunde a primeira carta">Primeira carta</button><button class="secondary" data-ask="O que isso significa na prática?">Na prática</button></div><form id="chat-form" class="chat-form"><input name="message" aria-label="Sua pergunta ao assistente" maxlength="500" required placeholder="Como interpretar esta combinação?"><button class="primary">Enviar</button></form></section><section class="panel reading" id="journal-note" tabindex="-1"><h3>Seu diário de reflexão</h3><label>O que esta leitura despertou?<textarea id="note" maxlength="3000" rows="4">'+esc(s.note)+'</textarea></label><div class="actions"><button id="save" class="primary">'+(s.saved?'Atualizar registro':'Salvar no diário')+'</button><button id="copy-reading" class="secondary">Copiar leitura</button><button id="share-reading" class="secondary">Exportar composição simbólica</button></div><small>Salvo apenas neste navegador. Não há sincronização entre dispositivos.</small></section>'}
let chatLimit=20;
function chatRender(){const msgs=[{role:'assistant',text:'Podemos examinar uma carta, a relação entre elas ou um próximo passo. Por onde gostaria de começar?'},...session.chat.slice(-chatLimit)];const older=Math.max(0,session.chat.length-chatLimit);$('#chat').innerHTML=(older?'<button type="button" id="chat-older" class="secondary">Mostrar mensagens anteriores ('+older+')</button>':'')+msgs.map(m=>'<div class="msg '+(m.role==='user'?'user':'')+'"><small>'+ (m.role==='user'?'Você':'Arcana')+'</small><br>'+esc(m.text)+'</div>').join('');if(older)$('#chat-older').onclick=()=>{chatLimit+=20;chatRender();$('#chat-older')?.focus()}}
function ask(q){if(!q.trim())return;const s=session;chatLimit=20;const answer=oracleReply(q.trim(),s);s.chat.push({role:'user',text:q.trim()},{role:'assistant',text:answer});s.saved=false;$('#save').textContent='Salvar alterações';persist();chatRender();$('#chat').scrollTop=$('#chat').scrollHeight;chime()}
function bindReading(){chatLimit=20;chatRender();const play=$('#narrate'),stop=$('#stop-narration'),status=$('#narration-status');play.disabled=!neuralAvailable();status.textContent=play.disabled?'Voz neural indisponível neste navegador.':'Voz neural local em português. Primeiro uso baixa o modelo e o motor; nenhum texto pessoal é enviado.';play.onclick=()=>{narrate(voiceScript(session),(state,message)=>{duckAmbient(state==='playing');if(!play.isConnected)return;const active=state==='loading'||state==='playing';play.disabled=active;stop.disabled=!active;status.textContent=message;play.setAttribute('aria-busy',String(state==='loading'))})};stop.onclick=()=>{stopNarration();duckAmbient(false);play.disabled=!neuralAvailable();stop.disabled=true;status.textContent='Narração interrompida.'};view.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const el=document.getElementById(b.dataset.jump);el.focus({preventScroll:true});el.scrollIntoView({behavior:calm()?'instant':'smooth'})});$('#chat-form').onsubmit=e=>{e.preventDefault();ask(new FormData(e.target).get('message'));e.target.reset()};view.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>ask(b.dataset.ask));$('#note').oninput=e=>{session.note=e.target.value;session.saved=false;$('#save').textContent='Salvar alterações';persist()};$('#save').onclick=()=>{const s=session,id=s.id||(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2)),record={id,date:new Date().toISOString(),spread:s.spread,...(s.spread==='custom'?{customSpread:snapshot(s.customSpread)}:{}),topic:s.topic,question:s.question,items:s.items,note:s.note,chat:s.chat};const next=[record,...history.filter(r=>r.id!==id)];if(!write('arcana-journal-v1',next)){toast('Não foi possível salvar neste navegador. Copie a leitura.');return}history=next;s.id=id;s.saved=true;persist();$('#save').textContent='Atualizar registro';toast('Tiragem registrada no diário.')};$('#share-reading').onclick=()=>{downloadArtwork(readingArtwork(session.items));toast('Composição simbólica preparada, sem pinturas ou anotações.');};$('#copy-reading').onclick=()=>{const r=interpret(session.items,session.spread,session.topic,session.customSpread);copy([spreadFor(session.spread,session.customSpread).name,session.question,r.summary,...r.cards.map(c=>c.position+' · '+c.name+(c.isReversed?' (invertida)':'')+': '+c.reading),...r.combos.map(c=>c.title+': '+c.text),r.focus,session.note].join('\n\n'))}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado.')}catch{const t=document.createElement('textarea');t.value=text;t.setAttribute('aria-label','Texto para copiar manualmente');const root=detail.open?detail:view;root.append(t);t.select();toast('Selecione e copie o texto exibido.')}}
function dailyView(){const c=dailyCard();view.innerHTML='<section class="section-head"><p class="eyebrow">O Observatório · '+esc(new Date().toLocaleDateString('pt-BR'))+'</p><h1>A carta do dia</h1><p class="lead">O mesmo símbolo permanece durante todo o dia neste navegador.</p></section><section class="panel daily-reading"><div class="daily-art rune-daily">'+runeHalo(c.id,true)+card(c,false,true)+'</div><div><p class="eyebrow">'+esc(c.suit)+'</p><h2>'+esc(c.name)+'</h2><p class="lead">'+esc(c.upright)+'</p><h3>Uma prática para hoje</h3><p>'+esc(c.action)+'.</p><p class="muted">'+esc(c.scene)+'</p><div class="actions"><button class="primary" id="daily-reflect">Refletir com esta carta</button><button class="secondary" id="daily-detail">Ver simbolismo</button></div></div></section>';watchImages();$('#daily-detail').onclick=()=>showCard(c);$('#daily-reflect').onclick=()=>{if(session&&!session.saved&&!confirm('Substituir a tiragem em andamento?'))return;session={spread:'one',topic:'general',question:'Reflexão da carta do dia',items:[daily.item],revealed:1,chat:[],note:'',saved:false,mode:'manual'};persist();location.hash='ritual'}}
function atlas(){view.innerHTML='<section class="section-head"><p class="eyebrow">A Biblioteca · Atlas dos arcanos</p><h1>O livro dos arcanos</h1><p class="lead">Conheça as 78 cartas, suas imagens, significados e símbolos. Passe o mouse ou navegue com o teclado para virar uma carta. Clique ou toque para consultar todos os detalhes.</p></section><div class="actions atlas-lab-link"><a class="secondary" href="#lab">Laboratório de combinações →</a><a class="secondary" href="#journey">Jornada do Louco →</a></div><div class="filterbar"><input id="search" aria-label="Buscar cartas" placeholder="Buscar carta ou significado…" value="'+esc(filter)+'"><select id="suit" aria-label="Filtrar por naipe">'+['Todos','Maiores','Paus','Copas','Espadas','Ouros'].map(x=>'<option '+(x===suit?'selected':'')+'>'+x+'</option>').join('')+'</select><button id="favorites" class="secondary" aria-pressed="'+onlyFavorites+'">Favoritas</button><span id="count" role="status"></span></div><div class="atlas-grid" id="grid"></div><div id="atlas-more" class="actions"></div>';$('#favorites').onclick=()=>{onlyFavorites=!onlyFavorites;atlasLimit=24;$('#favorites').setAttribute('aria-pressed',String(onlyFavorites));grid()};$('#search').oninput=e=>{filter=e.target.value;atlasLimit=24;grid()};$('#suit').onchange=e=>{suit=e.target.value;atlasLimit=24;grid()};grid()}
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function atlasCard(c){const category=c.arcana==='Maior'?'Arcano Maior':c.suit+' · Arcano Menor';return '<button type="button" class="atlas-item atlas-flippable" data-card="'+c.id+'" aria-label="'+esc(c.name+' — '+c.upright+'. Abrir detalhes')+'"><span class="atlas-flip-stage"><span class="atlas-flip-object"><span class="atlas-face atlas-front">'+card(c)+'</span><span class="atlas-face atlas-meaning" aria-hidden="true"><span class="atlas-category">'+esc(category)+'</span><span class="atlas-name">'+esc(c.name)+'</span><span class="atlas-element">'+esc(c.element)+'</span><span class="atlas-key"><b>Normal</b><span>'+esc(c.upright)+'</span></span><span class="atlas-key"><b>Invertida</b><span>'+esc(c.reversed)+'</span></span><span class="atlas-domain">'+esc(c.domain)+'</span><span class="atlas-more-label">Ver detalhes</span></span></span></span><small class="atlas-caption">'+esc(c.upright)+(favorites.includes(c.id)?' · Favorita':'')+'</small></button>'}
function grid(){const cards=deck.filter(c=>(!onlyFavorites||favorites.includes(c.id))&&(suit==='Todos'||c.suit===suit)&&norm(c.name+' '+c.upright+' '+c.reversed+' '+study(c.id).themes.join(' ')+' '+study(c.id).archetype).includes(norm(filter)));$('#count').textContent=cards.length+' cartas';$('#grid').innerHTML=cards.slice(0,atlasLimit).map(c=>atlasCard(c)).join('')||'<p>Nenhuma carta encontrada.</p>';$('#grid').querySelectorAll('[data-card]').forEach(b=>{b.onclick=()=>showCard(deck.find(c=>c.id===b.dataset.card));b.onpointerleave=()=>b.classList.remove('flip-dismissed');b.onblur=()=>b.classList.remove('flip-dismissed');b.onkeydown=e=>{if(e.key==='Escape'){b.classList.add('flip-dismissed');e.preventDefault()}}});watchImages($('#grid'));const more=$('#atlas-more');more.innerHTML=cards.length>atlasLimit?'<button id="load-more" class="secondary">Ver mais cartas ('+Math.min(atlasLimit,cards.length)+' de '+cards.length+')</button>':'';if($('#load-more'))$('#load-more').onclick=()=>{const start=atlasLimit;atlasLimit+=24;grid();const first=$('#grid').children[start];first?.focus({preventScroll:true});first?.scrollIntoView({block:'nearest',behavior:'instant'})}}
function showCard(c,rev=false){const k=study(c.id);$('#detail-content').innerHTML='<div class="detail-grid"><div class="rune-detail">'+runeHalo(c.id)+card(c,rev)+'</div>'+'<div><p class="eyebrow">'+esc(c.arcana)+' · '+esc(c.suit)+'</p><h2>'+esc(c.name)+'</h2><p class="card-characteristics"><strong>Elemento:</strong> '+esc(c.element)+' · <strong>Área:</strong> '+esc(c.domain)+'</p><p><strong>Normal:</strong> '+esc(c.upright)+'</p><p><strong>Invertida:</strong> '+esc(c.reversed)+'</p><p><strong>Símbolos:</strong> '+esc(c.scene)+'</p><p><strong>Reflexão:</strong> '+esc(c.action)+'.</p><section class="study-depth"><p class="eyebrow">Arquétipo · '+esc(k.archetype)+'</p><p>'+esc(k.depth)+'</p><div class="theme-tags">'+k.themes.map(t=>'<span>'+esc(t)+'</span>').join('')+'</div><p class="study-question">'+esc(k.question)+'</p></section></div></div><button id="favorite-card" class="secondary" aria-pressed="'+favorites.includes(c.id)+'">'+(favorites.includes(c.id)?'Remover dos favoritos':'Adicionar aos favoritos')+'</button>';detail.showModal();watchImages(detail);$('#favorite-card').onclick=()=>{const next=favorites.includes(c.id)?favorites.filter(id=>id!==c.id):[...favorites,c.id];if(!write('arcana-favorites-v1',next)){toast('Não foi possível salvar favorito.');return}favorites=next;$('#favorite-card').textContent=favorites.includes(c.id)?'Remover dos favoritos':'Adicionar aos favoritos';$('#favorite-card').setAttribute('aria-pressed',String(favorites.includes(c.id)));if(location.hash==='#atlas')grid()}}
function vaultState(){return {records:history,favorites,chapters:journeyDone,templates:customTemplates}}
function bindVault(){
 const section=$('#vault-panel'),password=$('#vault-password'),status=$('#vault-status'),file=$('#vault-file'),download=$('#vault-export'),restore=$('#vault-restore');let busy=false;
 const controls=on=>{busy=on;download.disabled=on;restore.disabled=on;password.disabled=on;file.disabled=on;section.setAttribute('aria-busy',String(on))};
 download.onclick=async()=>{if(busy)return;const pass=password.value;controls(true);status.textContent='Protegendo o cofre…';try{const text=await encryptVault(makeVault(vaultState()),pass);if(!section.isConnected)return;const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='arcana-cofre-'+localDay()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Cofre criptografado preparado. Guarde a senha em local seguro.'}catch(e){if(section.isConnected)status.textContent=e.message}finally{password.value='';controls(false)}};
 restore.onclick=async()=>{if(busy)return;const selected=file.files[0],pass=password.value;if(!selected){status.textContent='Escolha um arquivo de cofre.';return}if(selected.size>MAX_VAULT_FILE){status.textContent='Arquivo excede o limite de 7 MB.';return}controls(true);status.textContent='Verificando o cofre…';try{const incoming=await decryptVault(await selected.text(),pass);if(!section.isConnected)return;const merged=mergeVault(vaultState(),incoming),n=merged.added;if(!confirm('Importar '+n.records+' tiragem(ns), '+n.favorites+' favorito(s), '+n.chapters+' capítulo(s) e '+n.templates+' modelo(s)? Registros e modelos com o mesmo identificador mantêm a versão local.')){status.textContent='Importação cancelada.';return}if(!guard.fresh(COLLECTION_KEYS)){storageWarning(true);throw Error('Os dados mudaram em outra aba. Exporte o que deseja preservar e recarregue antes de importar.')}const next=applyVault(localStorage,merged.data);guard.refresh(COLLECTION_KEYS);history=next.records;favorites=next.favorites;journeyDone=next.chapters;journeyIndex=journeyResume(journeyDone);customTemplates=next.templates;journal();$('#vault-status').textContent='Cofre importado: '+n.records+' tiragem(ns), '+n.favorites+' favorito(s), '+n.chapters+' capítulo(s), '+n.templates+' modelo(s). '+merged.preserved.records+' leitura(s) e '+merged.preserved.templates+' modelo(s) já existentes foram preservados.'}catch(e){if(section.isConnected)status.textContent=e.message}finally{password.value='';file.value='';controls(false)}};
}

const JOURNAL_PAGE_SIZE=12;let journalPage=0,journalFilters={query:'',topic:'',month:'',day:''},calendarMonth=localDay().slice(0,7);
function journal(){const stats=journalStats(history);view.innerHTML='<section class="section-head"><p class="eyebrow">O Grimório · Diário dos símbolos</p><h1>Seu grimório</h1><p class="lead">Um atlas pessoal das suas leituras. Seus registros permanecem neste navegador.</p></section><section class="panel grimorio-overview" aria-labelledby="journal-overview-title"><h2 class="eyebrow" id="journal-overview-title">Sua jornada</h2><div class="grimorio-metrics"><div><strong>'+stats.readings+'</strong><small>Tiragens salvas</small></div><div><strong>'+stats.unique+'/78</strong><small>Arcanos encontrados</small></div><div><strong>'+stats.total+'</strong><small>Cartas reveladas</small></div><div><strong>'+stats.reversed+'</strong><small>Invertidas</small></div></div><div class="grimorio-progress" role="progressbar" aria-label="Arcanos encontrados" aria-valuemin="0" aria-valuemax="78" aria-valuenow="'+stats.unique+'"><i style="width:'+stats.unique/78*100+'%"></i></div><div class="grimorio-columns"><section><h3>Arcanos recorrentes</h3>'+(stats.frequent.length?stats.frequent.map(c=>'<button class="frequency-row" data-frequency="'+c.id+'"><span>'+esc(c.name)+'</span><span class="frequency-track"><i style="width:'+c.count/stats.frequent[0].count*100+'%"></i></span><b>'+c.count+'</b></button>').join(''):'<p class="muted">As frequências aparecem após salvar uma tiragem.</p>')+'<small>Contagens do histórico salvo, sem significado preditivo.</small></section><section><div class="calendar-head"><h3>Calendário</h3><label><span class="sr-only">Mês do calendário</span><input type="month" id="journal-month" value="'+calendarMonth+'"></label></div><div id="journal-calendar"></div></section></div></section><section class="panel"><h2>Registros</h2><div class="filterbar journal-filters"><input id="journal-search" aria-label="Buscar no diário" placeholder="Carta, pergunta ou anotação" value="'+esc(journalFilters.query)+'"><select id="journal-topic" aria-label="Filtrar por área"><option value="">Todas as áreas</option>'+Object.entries(topics).map(([k,v])=>'<option value="'+k+'" '+(journalFilters.topic===k?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select><button id="journal-clear" class="secondary">Limpar filtros</button></div><p id="journal-count" role="status"></p><div id="journal-list"></div><div id="journal-pagination" class="journal-pagination"></div></section><section class="panel journal-backup" aria-labelledby="journal-backup-title"><h2 class="section-compact-heading" id="journal-backup-title">Seus registros, suas escolhas</h2><p class="muted">Faça um backup local ou importe um diário ARCANA. Registros com o mesmo identificador são preservados.</p><div class="actions">'+(history.length?'<button id="export" class="secondary">Exportar diário (JSON)</button>':'')+'<button id="import" class="secondary">Importar backup</button><input id="import-file" type="file" accept=".json,application/json" hidden></div><p id="import-result" role="status"></p></section><section class="panel vault-panel" id="vault-panel" aria-labelledby="vault-title"><p class="eyebrow">O cofre dos símbolos</p><h2 class="section-compact-heading" id="vault-title">Leve sua jornada com você</h2><p class="muted">Proteja com senha um arquivo que reúne diário, favoritos, capítulos contemplados e modelos de rituais. Transfira-o para outro dispositivo e importe por aqui. Nenhum dado é enviado a um servidor. Tiragem em andamento, carta do dia e preferências ficam neste navegador.</p><label>Senha do cofre<input id="vault-password" type="password" autocomplete="new-password" minlength="12" maxlength="256" placeholder="Mínimo de 12 caracteres"></label><div class="actions"><button class="secondary" id="vault-export">Exportar cofre criptografado</button></div><label>Importar cofre<input type="file" id="vault-file" accept=".json,application/json"></label><div class="actions"><button class="secondary" id="vault-restore">Restaurar e unir dados</button></div><p class="muted">Não há recuperação de senha. Os backups JSON comuns do diário continuam disponíveis acima, sem criptografia.</p><p id="vault-status" role="status"></p></section>';bindVault();const renderCalendar=()=>{const days=monthDays(calendarMonth);$('#journal-calendar').innerHTML='<div class="calendar-grid">'+['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>'<span class="weekday">'+d+'</span>').join('')+days.map(day=>day?'<button type="button" class="calendar-day '+(stats.days[day]?'has-reading':'')+'" data-day="'+day+'" aria-label="'+day+' · '+(stats.days[day]||0)+' tiragens" aria-pressed="'+(journalFilters.day===day)+'">'+Number(day.slice(-2))+(stats.days[day]?'<i aria-hidden="true"></i>':'')+'</button>':'<span></span>').join('')+'</div>';view.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{journalPage=0;journalFilters.day=journalFilters.day===b.dataset.day?'':b.dataset.day;journalFilters.month='';renderCalendar();renderJournalList()})};renderCalendar();$('#journal-month').onchange=e=>{if(monthDays(e.target.value).length){calendarMonth=e.target.value;journalPage=0;journalFilters.month=calendarMonth;journalFilters.day='';renderCalendar();renderJournalList()}};$('#journal-search').oninput=e=>{journalPage=0;journalFilters.query=e.target.value;renderJournalList()};$('#journal-topic').onchange=e=>{journalPage=0;journalFilters.topic=e.target.value;renderJournalList()};$('#journal-clear').onclick=()=>{journalPage=0;journalFilters={query:'',topic:'',month:'',day:''};journal()};view.querySelectorAll('[data-frequency]').forEach(b=>b.onclick=()=>{journalPage=0;journalFilters.query=resolve({id:b.dataset.frequency,reversed:false}).name;$('#journal-search').value=journalFilters.query;renderJournalList()});renderJournalList();$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Arquivo excede o limite de 5 MB.');const text=await file.text();if(!e.target.isConnected)return;const result=importJournal(text,history);if(!write('arcana-journal-v1',result.records))throw Error('Não foi possível salvar o backup no navegador.');history=result.records;journal();$('#import-result').textContent=result.added+' registro(s) importado(s); '+result.skipped+' já existente(s).'}catch(err){if(e.target.isConnected)$('#import-result').textContent=err.message||'Não foi possível importar.'}finally{e.target.value=''}};if($('#export'))$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(journalBackup(history),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='arcana-diario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function renderJournalList(){const records=filterJournal(history,journalFilters),pages=Math.max(1,Math.ceil(records.length/JOURNAL_PAGE_SIZE));journalPage=Math.max(0,Math.min(pages-1,journalPage));const visible=records.slice(journalPage*JOURNAL_PAGE_SIZE,(journalPage+1)*JOURNAL_PAGE_SIZE);$('#journal-count').textContent=records.length+' de '+history.length+' registros'+(journalFilters.day?' · '+journalFilters.day:journalFilters.month?' · '+journalFilters.month:'');$('#journal-list').innerHTML=visible.length?visible.map(r=>'<article class="journal-entry grimorio-entry"><div class="journal-seal">'+constellation(r.items)+'</div><div><small>'+esc(new Date(r.date).toLocaleString('pt-BR'))+'</small><h3>'+esc(spreadFor(r.spread,r.customSpread).name)+'</h3><p>'+esc(r.question||topics[r.topic])+'</p><p class="muted">'+esc(r.items.map(i=>resolve(i).name+(i.reversed?' (invertida)':'')).join(' · '))+'</p><p>'+esc(r.note)+'</p><div class="actions"><button class="secondary" data-open="'+esc(r.id)+'">Revisitar</button><button class="secondary" data-seal="'+esc(r.id)+'">Salvar selo SVG</button><button class="secondary" data-share-art="'+esc(r.id)+'">Exportar composição</button><button class="secondary" data-delete="'+esc(r.id)+'">Excluir</button></div></div></article>').join(''):'<p class="muted">'+(history.length?'Nenhum registro corresponde aos filtros.':'Nenhuma tiragem salva ainda.')+'</p>'+(history.length?'':'<a class="primary" href="#ritual">Iniciar uma tiragem</a>');const pager=$('#journal-pagination');pager.innerHTML=pages>1?'<button class="secondary" id="journal-prev" '+(journalPage===0?'disabled':'')+'>Anterior</button><span aria-live="polite">Página '+(journalPage+1)+' de '+pages+'</span><button class="secondary" id="journal-next" '+(journalPage===pages-1?'disabled':'')+'>Próxima</button>':'';const turn=(delta)=>{journalPage+=delta;renderJournalList();const target=$('#journal-'+(delta>0?'next':'prev'));if(target&&!target.disabled)target.focus();else $('#journal-'+(delta>0?'prev':'next'))?.focus()};if(pages>1){$('#journal-prev').onclick=()=>turn(-1);$('#journal-next').onclick=()=>turn(1)};view.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const r=history.find(x=>x.id===b.dataset.open);if(session&&!session.saved&&!confirm('Substituir a tiragem em andamento?'))return;session={...r,revealed:r.items.length,saved:true,chat:Array.isArray(r.chat)?r.chat:[],mode:'manual'};persist();location.hash='ritual'});view.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Excluir este registro local?'))return;const next=history.filter(x=>x.id!==b.dataset.delete);if(!write('arcana-journal-v1',next)){toast('Não foi possível excluir.');return}history=next;if(session?.id===b.dataset.delete){delete session.id;session.saved=false;persist()}journal()});view.querySelectorAll('[data-share-art]').forEach(b=>b.onclick=()=>{const r=history.find(x=>x.id===b.dataset.shareArt);if(r)downloadArtwork(readingArtwork(r.items))});view.querySelectorAll('[data-seal]').forEach(b=>b.onclick=()=>{const r=history.find(x=>x.id===b.dataset.seal);const svg=constellation(r.items).replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" width="864" height="864" color="#d8b77b" ').replace('viewBox="-144 -144 288 288"','viewBox="-144 -144 288 288"').replace(/(<svg[^>]*>)/,'$1<rect x="-144" y="-144" width="288" height="288" fill="#111225"/>');const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='arcana-selo.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}

let labItems=[{id:'18-a-lua',reversed:false},{id:'19-o-sol',reversed:false}];
function lab(){view.innerHTML='<section class="section-head"><p class="eyebrow">A Biblioteca · Laboratório</p><h1>O diálogo dos símbolos</h1><p class="lead">Escolha duas ou três cartas e explore suas relações, sem alterar uma tiragem em andamento.</p></section><form id="lab-form" class="panel"><div class="lab-fields">'+labItems.map((item,i)=>'<fieldset class="lab-field"><legend>Carta '+(i+1)+'</legend><label>Arcano<select name="card-'+i+'">'+deck.map(c=>'<option value="'+c.id+'" '+(c.id===item.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label class="check"><input type="checkbox" name="rev-'+i+'" '+(item.reversed?'checked':'')+'> Invertida</label></fieldset>').join('')+'</div><div class="actions"><button class="primary">Explorar combinação</button><button type="button" class="secondary" id="lab-count">'+(labItems.length===2?'Adicionar terceira carta':'Remover terceira carta')+'</button></div><p id="lab-status" role="status"></p></form><div id="lab-result"></div>';const collect=()=>{const f=new FormData($('#lab-form'));return labItems.map((_,i)=>({id:f.get('card-'+i),reversed:f.has('rev-'+i)}))};$('#lab-count').onclick=()=>{labItems=collect();if(labItems.length===2){labItems.push({id:deck.find(c=>!labItems.some(x=>x.id===c.id)).id,reversed:false})}else labItems.pop();lab()};$('#lab-form').onsubmit=e=>{e.preventDefault();labItems=collect();labResult()};labResult()}
function labResult(){try{const result=compareCards(labItems);$('#lab-status').textContent='';$('#lab-result').innerHTML='<section class="panel"><div class="lab-cards">'+result.cards.map(c=>'<div>'+card(c,c.isReversed)+'<p class="muted">'+esc(c.meaning)+'</p></div>').join('')+'</div><div class="lab-mandala">'+constellation(labItems)+'</div><h2>Relações simbólicas</h2>'+result.pairs.map(p=>'<article class="lab-relation"><p class="eyebrow">'+esc(p.label)+'</p><h3>'+esc(p.title)+'</h3><p>'+esc(p.interpretation)+'</p><div class="theme-tags">'+p.themes.map(t=>'<span>'+esc(t)+'</span>').join('')+'</div></article>').join('')+'<h3>Perguntas de reflexão</h3>'+result.questions.map(q=>'<p>'+esc(q)+'</p>').join('')+'</section>';watchImages($('#lab-result'))}catch(e){$('#lab-status').textContent=e.message;$('#lab-result').innerHTML=''}}
let journeyDone=journeyProgress(read('arcana-journey-v1',[])),journeyIndex=journeyResume(journeyDone);
function journey(){const step=journeyCards[journeyIndex],c=resolve({id:step.id,reversed:false}),k=study(c.id),done=journeyDone.includes(c.id);view.innerHTML='<section class="section-head"><p class="eyebrow">A Biblioteca · A jornada dos arcanos</p><h1>A Jornada do Louco</h1><p class="lead">Vinte e dois capítulos de uma narrativa simbólica de aprendizado e transformação. Uma leitura autoral dos Arcanos Maiores, sem bloquear etapas ou exigir uma sequência.</p><a class="text-link" href="#atlas">Voltar ao baralho</a></section><section class="panel journey-panel"><div class="journey-progress"><span id="journey-count" role="status">'+journeyDone.length+' de 22 capítulos contemplados</span><progress max="22" value="'+journeyDone.length+'" aria-label="Progresso da jornada"></progress></div><div class="journey-chapters" aria-label="Capítulos">'+journeyCards.map((item,i)=>'<button type="button" data-chapter="'+i+'" title="'+esc(resolve({id:item.id,reversed:false}).name)+'" aria-label="'+esc('Capítulo '+(i+1)+': '+resolve({id:item.id,reversed:false}).name+(journeyDone.includes(item.id)?', contemplado':''))+'" '+(i===journeyIndex?'aria-current="step"':'')+' class="'+(journeyDone.includes(item.id)?'chapter-done':'')+'">'+String(i).padStart(2,'0')+'</button>').join('')+'</div><div class="journey-spread"><div class="journey-art">'+runeHalo(c.id,true)+card(c)+'</div><article class="journey-text"><p class="eyebrow">Capítulo '+(journeyIndex+1)+' · '+esc(step.title)+'</p><h2 id="chapter-title" tabindex="-1">'+esc(c.name)+'</h2><p class="lead">'+esc(step.story)+'</p><p>'+esc(k.depth)+'</p><div class="theme-tags">'+k.themes.map(t=>'<span>'+esc(t)+'</span>').join('')+'</div><p class="study-question">'+esc(k.question)+'</p><p><strong>Prática de contemplação:</strong> '+esc(step.practice)+'</p><div class="actions"><button class="primary" id="chapter-complete" aria-pressed="'+done+'">'+(done?'Marcar como não contemplado':'Marcar como contemplado')+'</button><button class="secondary" id="chapter-details">Estudar a carta</button></div></article></div><div class="journey-navigation"><button class="secondary" id="chapter-prev" '+(journeyIndex===0?'disabled':'')+'>← Anterior</button><button class="secondary" id="chapter-resume">Retomar jornada</button><button class="secondary" id="chapter-next" '+(journeyIndex===21?'disabled':'')+'>Próximo →</button></div>'+(journeyDone.length===22?'<p class="study-question" role="status">O círculo está completo. Você pode revisitar qualquer capítulo.</p>':'')+'</section>';watchImages();const go=i=>{journeyIndex=Math.max(0,Math.min(21,i));journey();$('#chapter-title').focus({preventScroll:true})};view.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>go(Number(b.dataset.chapter)));$('#chapter-prev').onclick=()=>go(journeyIndex-1);$('#chapter-next').onclick=()=>go(journeyIndex+1);$('#chapter-resume').onclick=()=>go(journeyResume(journeyDone));$('#chapter-details').onclick=()=>showCard(c);$('#chapter-complete').onclick=()=>{const next=toggleChapter(journeyDone,c.id);if(!write('arcana-journey-v1',next)){toast('Não foi possível salvar o progresso.');return}journeyDone=next;journey();$('#chapter-complete').focus({preventScroll:true})}}
let editingRitual=null;
const blankRitual=()=>({name:'',layout:'grid',positions:['Situação','Desafio','Integração'],lens:['Considere','Explore','Reflita sobre']});
let draftRitual=blankRitual();
function architect(){
 view.innerHTML='<section class="section-head"><p class="eyebrow">O Santuário · Arquiteto de Rituais</p><h1>Crie sua própria tiragem</h1><p class="lead">Defina de uma a dez posições, seus propósitos e a geometria da mesa.</p><a class="text-link" href="#ritual">Voltar à tiragem</a></section><section class="panel"><h2>Seus rituais</h2><div class="custom-library">'+(customTemplates.length?customTemplates.map(t=>'<article><h3>'+esc(t.definition.name)+'</h3><p class="muted">'+t.definition.positions.length+' cartas · '+esc(({grid:'Grade',line:'Linha',circle:'Círculo'})[t.definition.layout])+'</p><div class="actions"><button class="primary" data-custom-start="'+t.id+'">Usar ritual</button><button class="secondary" data-custom-edit="'+t.id+'">Editar</button><button class="secondary" data-custom-delete="'+t.id+'">Excluir</button></div></article>').join(''):'<p class="muted">Nenhum ritual personalizado salvo.</p>')+'</div><button class="secondary" id="custom-new">Novo ritual</button></section><form class="panel" id="custom-form"><h2>'+ (editingRitual?'Editar ritual':'Novo ritual')+'</h2><div class="fields"><label>Nome<input required maxlength="80" name="name" value="'+esc(draftRitual.name)+'" placeholder="Ex.: O espelho interior"></label><label>Disposição<select name="layout">'+[['grid','Grade'],['line','Linha'],['circle','Círculo']].map(([id,label])=>'<option value="'+id+'" '+(draftRitual.layout===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><div id="custom-positions"></div><div class="actions"><button class="secondary" type="button" id="custom-add">Adicionar posição</button><button class="secondary" type="button" id="custom-remove">Remover última</button></div><h3>Prévia da mesa</h3><div id="custom-preview"></div><p class="muted">O propósito é uma frase introdutória da interpretação. Ex.: “O recurso a explorar envolve”. Em telas estreitas, a mesa usa uma grade responsiva.</p><div class="actions"><button class="primary" type="submit">Salvar ritual</button></div><p id="custom-status" role="status"></p></form>';
 const form=$('#custom-form');
 function collect(){draftRitual.name=form.elements.namedItem('name').value;draftRitual.layout=form.elements.namedItem('layout').value;draftRitual.positions=draftRitual.positions.map((_,i)=>form.elements.namedItem('position-'+i).value);draftRitual.lens=draftRitual.lens.map((_,i)=>form.elements.namedItem('lens-'+i).value)}
 function preview(){const cells=layoutCells(draftRitual.positions.length,draftRitual.layout);$('#custom-preview').innerHTML='<div class="architect-preview custom-'+draftRitual.layout+(cells.length?' custom-ring':'')+'" style="--custom-count:'+draftRitual.positions.length+'">'+draftRitual.positions.map((p,i)=>'<div '+(cells[i]?'style="--cell-x:'+cells[i][0]+';--cell-y:'+cells[i][1]+'"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span><small>'+esc(p||'Posição '+(i+1))+'</small></div>').join('')+'</div>'}
 function positions(){$('#custom-positions').innerHTML=draftRitual.positions.map((p,i)=>'<fieldset class="architect-position"><legend>Posição '+(i+1)+'</legend><label>Título<input required maxlength="80" name="position-'+i+'" value="'+esc(p)+'"></label><label>Propósito da posição<input required maxlength="160" name="lens-'+i+'" value="'+esc(draftRitual.lens[i])+'"></label></fieldset>').join('');$('#custom-add').disabled=draftRitual.positions.length>=10;$('#custom-remove').disabled=draftRitual.positions.length<=1;preview()}
 positions();form.oninput=()=>{collect();preview()};form.elements.namedItem('layout').onchange=()=>{collect();preview()};$('#custom-add').onclick=()=>{collect();if(draftRitual.positions.length<10){draftRitual.positions.push('Posição '+(draftRitual.positions.length+1));draftRitual.lens.push('Considere');positions()}};$('#custom-remove').onclick=()=>{collect();if(draftRitual.positions.length>1){draftRitual.positions.pop();draftRitual.lens.pop();positions()}};
 form.onsubmit=e=>{e.preventDefault();collect();try{const def=snapshot(draftRitual);if(!editingRitual&&customTemplates.length>=50)throw Error('Limite de 50 rituais. Exclua um modelo antes de criar outro.');const id=editingRitual||(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));const next=[{id,definition:def},...customTemplates.filter(t=>t.id!==id)];if(!write('arcana-custom-rituals-v1',next))throw Error('Não foi possível salvar.');customTemplates=next;editingRitual=null;draftRitual=blankRitual();architect();toast('Ritual salvo.')}catch(err){$('#custom-status').textContent=err.message}};
 $('#custom-new').onclick=()=>{editingRitual=null;draftRitual=blankRitual();architect();$('#custom-form input').focus()};
 view.querySelectorAll('[data-custom-edit]').forEach(b=>b.onclick=()=>{editingRitual=b.dataset.customEdit;draftRitual=snapshot(customTemplates.find(t=>t.id===editingRitual).definition);architect();$('#custom-form input').focus()});
 view.querySelectorAll('[data-custom-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Excluir este modelo? Tiragens já salvas serão preservadas.'))return;const next=customTemplates.filter(t=>t.id!==b.dataset.customDelete);if(!write('arcana-custom-rituals-v1',next))return;customTemplates=next;if(editingRitual===b.dataset.customDelete){editingRitual=null;draftRitual=blankRitual()}architect()});
 view.querySelectorAll('[data-custom-start]').forEach(b=>b.onclick=()=>{if(session&&!session.saved&&!confirm('Substituir a tiragem em andamento?'))return;session=null;persist();selectedTemplate=b.dataset.customStart;location.hash='ritual'});
}
let lastRoute='';function route(){stopNarration();document.body.classList.toggle('optimized-art',optimizedArt);cancelReveal();const requested=location.hash.slice(1)||'home';const name=requested==='museum'?'atlas':requested;if(requested==='museum')window.history.replaceState(null,'','#atlas');document.body.dataset.scene=name==='architect'?'ritual':(name==='lab'||name==='journey')?'atlas':['home','ritual','daily','atlas','journal'].includes(name)?name:'home';showScene(document.body.dataset.scene,optimizedArt);if(ambience)ambient(true,document.body.dataset.scene);document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+(name==='architect'?'ritual':name==='journey'?'atlas':name))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({home,ritual:()=>ritual(),atlas,lab,journey,architect,journal,daily:dailyView}[name]||home)();if(lastRoute!==name){view.classList.remove('route-enter');void view.offsetWidth;view.classList.add('route-enter');lastRoute=name}window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
